import math
import struct

M63 = (1 << 63) - 1


def f32(x):
    return struct.unpack('f', struct.pack('f', x))[0]


class Rng:
    """Встроенный ГСЧ (spec rng): слова WELL512a; irandom/irandom_range — 2 слова (младшее, старшее), 63 бита."""
    def __init__(s, w):
        s.w = w
        s.n = 0

    def u(s):
        s.n += 1
        return s.w.u32()

    def irr(s, a, b):
        lo_w = s.u()
        hi_w = s.u()
        U = ((hi_w << 32) | lo_w) & M63
        lo, hi = min(a, b), max(a, b)
        return lo + U % (hi - lo + 1)

    def irandom(s, n):
        lo_w = s.u()
        hi_w = s.u()
        return (((hi_w << 32) | lo_w) & M63) % (n + 1)


def clamp(v, a, b):
    return max(a, min(b, v))


def fdist(dx, dy):
    a = f32(dx)
    b = f32(dy)
    return f32(math.sqrt(f32(f32(a * a) + f32(b * b))))


