export function makeVeinmorpher(d) {
  const C = d.constants, e = C['compare.eps'];
  const gt = (x, y) => x - y > e;
  const chance = (a, b, rng) => !gt(Number(rng.u63() % BigInt(Math.trunc(b))) + 1, a);
  function apply(rocks, s, rng) {
    const a = C['roll.scale'] * s.p;
