// Этап 7.7: двухвыборочный критерий Колмогорова — Смирнова. Статистика D = max |F_a − F_b| по объединённой выборке
// (совпадающие значения — одной ступенью, поэтому ничьи обрабатываются честно). p-значение — точное перестановочное
// (все C(n+m, n) разбиений объединённой выборки) при n + m ≤ 24, иначе асимптотика Колмогорова.
export function ksD(a, b) {
  const xs = [...new Set([...a, ...b])].sort((x, y) => x - y);
  const cnt = (v, x) => v.reduce((k, y) => k + (y <= x ? 1 : 0), 0);
  let d = 0;
  for (const x of xs) d = Math.max(d, Math.abs(cnt(a, x) / a.length - cnt(b, x) / b.length));
  return d;
}

function asymP(d, n, m) {
  const en = Math.sqrt((n * m) / (n + m));
  const l = (en + 0.12 + 0.11 / en) * d;
  if (l < 1e-9) return 1;
  let s = 0;
  for (let j = 1; j <= 100; j++) s += 2 * (-1) ** (j - 1) * Math.exp(-2 * j * j * l * l);
  return Math.min(1, Math.max(0, s));
}

// точное перестановочное p = доля разбиений с D ≥ D_набл (с допуском на округление)
